import type { FamilyLabelMatch } from "#src/models/genshinAssets/camps/FamilyLabelMatch";

import { toEnemyKindIdMember } from "#src/services/genshinAssets/camps/toEnemyKindIdMember";
import { toPropertyKey } from "#src/services/genshinAssets/camps/toPropertyKey";

// The source of the family-label map the camps read, one line a label in alphabetical order
export const toFamilyLabelMapSource = (matches: readonly FamilyLabelMatch[]): string =>
  [
    'import { EnemyKindId } from "genshin-world/definitions";',
    "",
    "// Generated by `pnpm -C scripts genshin:assets family-labels` from the enemy pages in the wiki cache: each family label",
    "// A camp names maps to the lowest-id kind the world holds of a family its pages list. Not edited by hand",
    "export const FamilyLabelEnemyKindIdMap: Record<string, EnemyKindId> = {",
    ...matches
      .toSorted((firstMatch, secondMatch) => firstMatch.label.localeCompare(secondMatch.label))
      .map(({ kindId, label }) => `  ${toPropertyKey(label)}: EnemyKindId.${toEnemyKindIdMember(kindId)},`),
    "};",
    "",
  ].join("\n");
